//! Carbon's completion as an RLX program, answering `generate`: what
//! `CarbonRunner::complete` does around the backbone, from the crate's own
//! `dna_config.rs` and `hybrid.rs` — the prompt opened as a DNA region where
//! asked, encoded (text by the package's tokenizer, nucleotides by the
//! 6-mer table), the ids generated by the package's `generate` entry, the
//! continuation decoded.
//!
//! In: the prompt; options `max_tokens` (default 64), `as_dna` (default the
//! config's `auto_dna_tags`) and the entry's sampling options. Out: `text`.

#[allow(dead_code)]
#[path = "../../src/dna_config.rs"]
mod dna_config;
#[allow(dead_code)]
#[path = "../../src/hybrid.rs"]
mod hybrid;

use anyhow::anyhow;
use dna_config::DnaConfig;
use rlx_program::{Message, Program, Tensor, host};
use serde_json::{Value, json};

struct Base {
    tokenizer: String,
}

impl hybrid::Bpe for Base {
    fn encode(&self, text: &str) -> anyhow::Result<Vec<u32>> {
        let m = host(
            "tokenizer.encode",
            Message::body(json!({"tokenizer": self.tokenizer, "text": text, "special": false})),
        )
        .map_err(|e| anyhow!(e))?;
        Ok(m.body["ids"]
            .as_array()
            .ok_or_else(|| anyhow!("tokenizer.encode returned no ids"))?
            .iter()
            .filter_map(Value::as_u64)
            .map(|v| v as u32)
            .collect())
    }

    /// The package's decode; it drops special tokens as `skip_special_tokens`
    /// does, which is how the runner decodes a completion.
    fn decode(&self, ids: &[u32], _skip_special_tokens: bool) -> anyhow::Result<String> {
        let m = host(
            "tokenizer.decode",
            Message::body(json!({"tokenizer": self.tokenizer, "ids": ids})),
        )
        .map_err(|e| anyhow!(e))?;
        Ok(m.body["text"].as_str().unwrap_or_default().to_string())
    }
}

struct Carbon {
    base: Base,
    dna: DnaConfig,
    eos: u32,
}

impl Carbon {
    fn complete(&self, prompt: &str, options: &Value) -> anyhow::Result<String> {
        let max_tokens = options["max_tokens"].as_u64().unwrap_or(64);
        let as_dna = options["as_dna"].as_bool();
        let treat_dna = !prompt.contains("<dna>") && as_dna.unwrap_or(self.dna.auto_dna_tags);
        let text = if treat_dna {
            format!("<dna>{prompt}")
        } else {
            prompt.to_string()
        };
        let ids = hybrid::encode(&self.base, &self.dna, &text, false)?;
        let ids: Vec<i32> = ids.iter().map(|&t| t as i32).collect();
        let mut opts = options.clone();
        if !opts.is_object() {
            opts = json!({});
        }
        opts["max_tokens"] = json!(max_tokens);
        opts["stop_ids"] = json!([self.eos]);
        let out = host(
            "entry.run",
            Message::new(
                json!({"entry": "generate", "options": opts}),
                vec![Tensor::i32("input_ids", vec![ids.len()], &ids)],
            ),
        )
        .map_err(|e| anyhow!(e))?;
        let generated: Vec<u32> = out
            .tensors
            .first()
            .ok_or_else(|| anyhow!("the generate entry returned nothing"))?
            .to_i64()
            .into_iter()
            .map(|t| t as u32)
            .take_while(|&t| t != self.eos)
            .collect();
        hybrid::decode(&self.base, &self.dna, &generated, true, self.eos, self.eos)
    }
}

impl Program for Carbon {
    fn init(config: Value) -> Result<Self, String> {
        Ok(Carbon {
            base: Base {
                tokenizer: config["tokenizer"]
                    .as_str()
                    .ok_or("config has no tokenizer")?
                    .to_string(),
            },
            dna: serde_json::from_value(config["dna"].clone())
                .map_err(|e| format!("config dna: {e}"))?,
            eos: config["eos"].as_u64().ok_or("config has no eos")? as u32,
        })
    }

    fn call(&mut self, task: &str, req: Message) -> Result<Message, String> {
        if task != "generate" {
            return Err(format!("Carbon answers generate, not {task}"));
        }
        let prompt = req.body["prompt"]
            .as_str()
            .ok_or("generate takes a prompt")?;
        let text = self
            .complete(prompt, &req.body["options"])
            .map_err(|e| format!("{e:#}"))?;
        Ok(Message::body(json!({"text": text})))
    }
}

rlx_program::program!(Carbon);
